// Build a compact summary object from all three API responses
const commits = $('Fetch Commits (7d)').all();
const issues  = $('Fetch Closed Issues (7d)').all();
const prs     = $('Fetch Merged PRs (7d)').all();

const since = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

// Commits
const commitList = (commits[0]?.json ?? []).map(c => ({
  sha:     c.sha?.slice(0, 7),
  message: c.commit?.message?.split('\n')[0] ?? '',
  author:  c.commit?.author?.name ?? 'unknown',
  date:    c.commit?.author?.date,
}));

// Issues closed this week (filter out PRs — GitHub returns PRs in issues endpoint)
const issueList = (issues[0]?.json ?? [])
  .filter(i => !i.pull_request && new Date(i.closed_at) >= since)
  .map(i => ({
    number: i.number,
    title:  i.title,
    labels: i.labels?.map(l => l.name) ?? [],
    closer: i.closed_by?.login ?? 'unknown',
  }));

// PRs merged this week
const prList = (prs[0]?.json ?? [])
  .filter(p => p.merged_at && new Date(p.merged_at) >= since)
  .map(p => ({
    number:    p.number,
    title:     p.title,
    author:    p.user?.login ?? 'unknown',
    mergedAt:  p.merged_at,
    additions: p.additions,
    deletions: p.deletions,
  }));

const language = $env.SUMMARY_LANGUAGE?.toUpperCase() === 'FR' ? 'French' : 'English';

const repo = `${$env.GITHUB_REPO_OWNER}/${$env.GITHUB_REPO_NAME}`;
const weekEnd = new Date().toISOString().split('T')[0];

return [{
  json: {
    repo,
    weekEnd,
    language,
    stats: {
      commitCount: commitList.length,
      issuesClosed: issueList.length,
      prsMerged: prList.length,
    },
    commits:  commitList.slice(0, 40),
    issues:   issueList,
    prs:      prList,
  }
}];

// Build the Claude prompt from the context object
const ctx = $input.first().json;

const commitLines = ctx.commits
  .map(c => `  - [${c.sha}] ${c.message} (${c.author})`)
  .join('\n');

const issueLines = ctx.issues.length
  ? ctx.issues.map(i => `  - #${i.number}: ${i.title} — closed by @${i.closer}`).join('\n')
  : '  (none)';

const prLines = ctx.prs.length
  ? ctx.prs.map(p => `  - #${p.number}: ${p.title} by @${p.author}`).join('\n')
  : '  (none)';

const langInstruction = ctx.language === 'French'
  ? 'Write the summary entirely in French.'
  : 'Write the summary in English.';

const prompt = `You are a senior engineering manager writing a weekly team newsletter.

Repository: ${ctx.repo}
Week ending: ${ctx.weekEnd}
${langInstruction}

Here is the raw activity data from this week:

COMMITS (${ctx.stats.commitCount} total — sample shown):
${commitLines || '  (none)'}

ISSUES CLOSED (${ctx.stats.issuesClosed}):
${issueLines}

PULL REQUESTS MERGED (${ctx.stats.prsMerged}):
${prLines}

---

Write a warm, engaging **weekly development summary** in the following format:

## 🗓 Weekly Dev Digest — ${ctx.weekEnd}

**Highlights** (2–3 sentence executive summary of what happened this week)

**✨ What shipped**
Bullet list of the most impactful merged PRs and closed issues.

**⚙️ Under the hood**
Brief paragraph about commit patterns, refactors, chores — what the team was working on day-to-day.

**📊 By the numbers**
- Commits: ${ctx.stats.commitCount}
- Issues closed: ${ctx.stats.issuesClosed}
- PRs merged: ${ctx.stats.prsMerged}

**👀 Looking ahead**
One sentence of encouragement or focus for next week (inferred from the activity).

Keep the tone professional but human. No more than 350 words total.`;

return [{ json: { prompt, ctx } }];

const claudeResponse = $input.first().json;
const summaryText = claudeResponse.content?.[0]?.text ?? '(Claude returned no text)';
const ctx = $('Build Claude Prompt').first().json.ctx;

return [{
  json: {
    summaryText,
    repo: ctx.repo,
    weekEnd: ctx.weekEnd,
    stats: ctx.stats,
  }
}];

